using System;using System.IO;using System.Collections.Generic;
class BatchFixturesFG {
 static byte[] keys=new byte[334];static void Save(string folder,string name,byte[] bytes){using(FileStream f=new FileStream(Path.Combine(folder,name),FileMode.CreateNew,FileAccess.Write))f.Write(bytes,0,bytes.Length);}
 static byte[] Frame(ushort op,byte[] body){byte[] b=new byte[13+body.Length];b[0]=1;BitConverter.GetBytes(op).CopyTo(b,1);BitConverter.GetBytes(b.Length).CopyTo(b,3);body.CopyTo(b,13);return b;}
 static void Quest(string folder,ushort op,ushort id){byte[] plain=new byte[op==35?8:16];BitConverter.GetBytes(op).CopyTo(plain,0);BitConverter.GetBytes(id).CopyTo(plain,2);if(op==36){BitConverter.GetBytes(ushort.MaxValue).CopyTo(plain,4);BitConverter.GetBytes((ushort)1).CopyTo(plain,6);}Save(folder,"request"+op+"-"+id+".bin",Frame(op,Offline70FlowCipherFG.Crypt(plain,keys,op%14,true)));}
 static int Main(string[] args){if(args.Length!=3)return 2;Directory.CreateDirectory(args[0]);for(int i=0;i<334;i++)keys[i]=(byte)i;foreach(ushort id in new ushort[]{101,102,103,1146})foreach(ushort op in new ushort[]{33,35,36})Quest(args[0],op,id);
  byte[] move=File.ReadAllBytes(args[1]);if(move.Length!=72)throw new InvalidDataException("Captured move fixture size");foreach(byte y in new byte[]{0,1,2}){move[1]=y;Save(args[0],"move-"+y+".bin",Frame(48,Offline70FlowCipherFG.Crypt(move,keys,6,true)));}
  byte[] death=File.ReadAllBytes(args[2]);if(death.Length!=68)throw new InvalidDataException("Captured death fixture size");byte[] d=Offline70RoleProtocol.BatchCryptFG(death,keys,0,false),body=new byte[64];Buffer.BlockCopy(d,0,body,0,64);foreach(ushort uid in new ushort[]{100,101,102,103,104,105,106}){BitConverter.GetBytes(uid).CopyTo(body,0);Save(args[0],"kill-"+uid+".bin",Frame(42,Offline70RoleProtocol.BatchCryptFG(Offline70RoleProtocol.WithDungeonIntegrity(body),keys,0,true)));}
  for(ushort slot=2000;slot<=2063;slot++){byte[] p=new byte[16];BitConverter.GetBytes(slot).CopyTo(p,0);p[3]=1;Save(args[0],"pickup-"+slot+".bin",Frame(46,Offline70GoldCipher.Crypt(p,keys,4,true)));}
  foreach(byte state in new byte[]{0,1}){byte[] exit=new byte[16];exit[0]=state;Save(args[0],"channel-exit-"+state+".bin",Frame(3,Offline70KeySettings.Crypt(exit,keys,true)));}Save(args[0],"abort45.bin",Frame(45,new byte[0]));
  byte[] score=new byte[40];score[0]=1;Save(args[0],"clear49.bin",Frame(49,Offline70FlowCipherFG.Crypt(Offline70GoldLoot.Pad(Offline70RoleProtocol.WithDungeonIntegrity(score),8),keys,7,true)));foreach(byte option in new byte[]{0,1,2,3})Save(args[0],"end-"+option+".bin",Frame(75,Offline70RoleProtocol.Xtea(new byte[]{1,option,0,0,0,0,0,0},keys,true)));
  foreach(uint tick in new uint[]{1,2,3}){byte[] use=new byte[16];BitConverter.GetBytes((ushort)57).CopyTo(use,0);BitConverter.GetBytes((uint)1000).CopyTo(use,7);BitConverter.GetBytes(tick).CopyTo(use,11);Save(args[0],"use-"+tick+".bin",Frame(47,Offline70RoleProtocol.Xtea(use,keys,true)));}
  foreach(bool equip in new bool[]{true,false}){byte[] r=new byte[32];r[0]=(byte)(equip?1:3);BitConverter.GetBytes((ushort)(equip?0:1)).CopyTo(r,1);BitConverter.GetBytes((uint)39401).CopyTo(r,3);BitConverter.GetBytes((uint)1).CopyTo(r,7);r[11]=(byte)(equip?3:1);BitConverter.GetBytes((ushort)(equip?1:0)).CopyTo(r,12);BitConverter.GetBytes((uint)(equip?10:11)).CopyTo(r,18);Save(args[0],equip?"avatar-equip.bin":"avatar-remove.bin",Frame(19,Offline70RoleProtocol.Xtea(r,keys,true)));}
  Console.WriteLine("PASS batch fixture generation from original captured move/death");return 0;
 }
}
